//! UI copy comes from `i18n/en.yaml` and `i18n/zh.yaml`, generated by `build.rs`.
//! `Lang` lives in a gpui Global; views call `t(cx, TextKey::…)`.

use gpui_kit::{App, Global, UpdateGlobal as _};

include!(concat!(env!("OUT_DIR"), "/i18n_generated.rs"));

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Lang {
    #[default]
    Auto,
    En,
    Zh,
}

impl Lang {
    pub fn parse(value: Option<&str>) -> Self {
        match value {
            Some("en") => Self::En,
            Some("zh") => Self::Zh,
            _ => Self::Auto,
        }
    }

    fn zh(self) -> bool {
        match self {
            Self::Zh => true,
            Self::En => false,
            // auto: no locale detection wired yet; default to Chinese UI like the
            // primary deployment. ponytail: pick up system locale if needed.
            Self::Auto => true,
        }
    }

    fn locale(self) -> Locale {
        if self.zh() { Locale::ZhCn } else { Locale::EnUs }
    }
}

/// Resolved language for rendering. `Auto` resolves here once, at startup.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct UiLang(pub Lang);

impl Global for UiLang {}

pub fn init(lang: Lang, cx: &mut App) {
    cx.set_global(UiLang(lang));
}

pub fn current(cx: &App) -> Lang {
    cx.global::<UiLang>().0
}

pub fn set(lang: Lang, cx: &mut App) {
    UiLang::update_global(cx, |ui, _| ui.0 = lang);
}

pub fn t(cx: &App, key: TextKey) -> &'static str {
    text(current(cx).locale(), key)
}

pub fn t_args(cx: &App, key: TextKey, vars: &[(&str, &str)]) -> String {
    text_with_args(current(cx).locale(), key, vars)
}

/// `t(cx, key)` shorthand.
#[macro_export]
macro_rules! t {
    ($cx:expr, $key:expr) => {
        $crate::dict::t($cx, $key)
    };
}
